    (v_id, $q$Energy Cost$q$, $q$Energy Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Energy} * {Energy Price}$q$, 14, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Heating Time} / {Billets in Coil}$q$, 15, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Forging - Induction heating$q$
  WHERE process_group = $q$Forging$q$ AND operation IN ($q$Conveyor Induction Heat$q$);
