$calc$;

-- Forging - Forging load
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Forging - Forging load$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Forging - Forging load$q$, 'process', 'single', false, true, true, $q$The force to close the dies on the finishing impression: load factor x flow stress x projected area with the flash land (the empirical rule of Schey, Kalpakjian and Groover). The flow stress is the alloy's strength coefficient x strain rate ^ strain rate sensitivity at forging temperature (Altan), the strain rate being the ram speed over the forging's mean height. The load factor is 6 for a simple shape with flash, 8 for a complex one and 10 for a very complex one (Groover); which of the three a part is, is taken here from the shape complexity of EN 10243-1, the forging's volume over that of its enveloping box (above 0.63, above 0.32, below). That pairing of the two published rules is eMithran's own and is not verified against production.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The force to close the dies on the finishing impression: load factor x flow stress x projected area with the flash land (the empirical rule of Schey, Kalpakjian and Groover). The flow stress is the alloy's strength coefficient x strain rate ^ strain rate sensitivity at forging temperature (Altan), the strain rate being the ram speed over the forging's mean height. The load factor is 6 for a simple shape with flash, 8 for a complex one and 10 for a very complex one (Groover); which of the three a part is, is taken here from the shape complexity of EN 10243-1, the forging's volume over that of its enveloping box (above 0.63, above 0.32, below). That pairing of the two published rules is eMithran's own and is not verified against production.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Projected Area$q$, $q$Projected Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Parting Perimeter$q$, $q$Parting Perimeter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Envelope Volume$q$, $q$Envelope Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Land Width$q$, $q$Land Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Forged Volume$q$, $q$Forged Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Ram Speed$q$, $q$Ram Speed (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Strength Coefficient$q$, $q$Strength Coefficient (MPa)$q$, $q$number$q$, $q$MPa$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Strain Rate Sensitivity$q$, $q$Strain Rate Sensitivity$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Flash Land Area$q$, $q$Flash Land Area (mm²)$q$, $q$calculated$q$, $q$mm²$q$, NULL, NULL, NULL, $q${Parting Perimeter} * {Land Width}$q$, 9, false),
    (v_id, $q$Loaded Area$q$, $q$Loaded Area (mm²)$q$, $q$calculated$q$, $q$mm²$q$, NULL, NULL, NULL, $q${Projected Area} + {Flash Land Area}$q$, 10, false),
    (v_id, $q$Mean Height$q$, $q$Mean Height (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Forged Volume} / {Projected Area}$q$, 11, false),
    (v_id, $q$Strain Rate$q$, $q$Strain Rate (1/s)$q$, $q$calculated$q$, $q$1/s$q$, NULL, NULL, NULL, $q${Ram Speed} / {Mean Height}$q$, 12, false),
    (v_id, $q$Flow Stress$q$, $q$Flow Stress (MPa)$q$, $q$calculated$q$, $q$MPa$q$, NULL, NULL, NULL, $q${Strength Coefficient} * {Strain Rate} ^ {Strain Rate Sensitivity}$q$, 13, false),
    (v_id, $q$Shape Complexity$q$, $q$Shape Complexity$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q${Forged Volume} / {Envelope Volume}$q$, 14, false),
    (v_id, $q$Load Factor (unverified rule)$q$, $q$Load Factor (unverified rule)$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$IF({Shape Complexity} > 0.63, 6, IF({Shape Complexity} > 0.32, 8, 10))$q$, 15, false),
    (v_id, $q$Forging Load$q$, $q$Forging Load (kN)$q$, $q$calculated$q$, $q$kN$q$, NULL, NULL, NULL, $q${Load Factor (unverified rule)} * {Flow Stress} * {Loaded Area} / 1000$q$, 16, false);
END
$calc$;

