-- Forging - Mechanical press
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Forging - Mechanical press$q$ AND user_id IS NULL AND retired_at IS NULL;
