-- Forging - Die tooling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Forging - Die tooling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Forging - Die tooling$q$, 'process', 'single', false, true, true, $q$The dies of the route over the parts made in the tool's life. The reference data gives one rule, for the cavity of a die: its CNC setup and its rough machining at the tool shop's machining rate, valid between a lowest and a highest cost for the finishing die and for the blocking impression. That rule covers neither the die block nor finishing and polishing the cavity, so the result is nearly always the lowest valid cost. The trim die and the piercing die have only their lowest and highest valid cost, without a rule: they are taken at the lowest. The tooling is therefore a lower figure, not an estimate of a particular die.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The dies of the route over the parts made in the tool's life. The reference data gives one rule, for the cavity of a die: its CNC setup and its rough machining at the tool shop's machining rate, valid between a lowest and a highest cost for the finishing die and for the blocking impression. That rule covers neither the die block nor finishing and polishing the cavity, so the result is nearly always the lowest valid cost. The trim die and the piercing die have only their lowest and highest valid cost, without a rule: they are taken at the lowest. The tooling is therefore a lower figure, not an estimate of a particular die.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
