    (v_id, $q$Pierced Holes$q$, $q$Pierced Holes$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Tool Shop Machining Rate$q$, $q$Tool Shop Machining Rate (USD/hr)$q$, $q$number$q$, $q$USD/hr$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Lifetime Volume$q$, $q$Lifetime Volume (parts)$q$, $q$number$q$, $q$parts$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Cavity CNC Setup$q$, $q$Cavity CNC Setup (hr)$q$, $q$number$q$, $q$hr$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Rough Machining Rate$q$, $q$Rough Machining Rate (hr/in³)$q$, $q$number$q$, $q$hr/in³$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Lowest Finish Die Cost$q$, $q$Lowest Finish Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Highest Finish Die Cost$q$, $q$Highest Finish Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Lowest Blocking Die Cost$q$, $q$Lowest Blocking Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 11, true),
    (v_id, $q$Highest Blocking Die Cost$q$, $q$Highest Blocking Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Lowest Trim Die Cost$q$, $q$Lowest Trim Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 13, true),
    (v_id, $q$Lowest Pierce Die Cost$q$, $q$Lowest Pierce Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 14, true),
    (v_id, $q$Cavity Volume$q$, $q$Cavity Volume (in³)$q$, $q$calculated$q$, $q$in³$q$, NULL, NULL, NULL, $q${Forged Volume} / 16387.064$q$, 15, false),
    (v_id, $q$Cavity Machining Cost$q$, $q$Cavity Machining Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$({Cavity CNC Setup} + {Rough Machining Rate} * {Cavity Volume}) * {Tool Shop Machining Rate}$q$, 16, false),
    (v_id, $q$Finish Die Cost$q$, $q$Finish Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$min(max({Cavity Machining Cost}, {Lowest Finish Die Cost}), {Highest Finish Die Cost})$q$, 17, false),
    (v_id, $q$Blocking Die Cost$q$, $q$Blocking Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Blocking Impression} * min(max({Cavity Machining Cost}, {Lowest Blocking Die Cost}), {Highest Blocking Die Cost})$q$, 18, false),
    (v_id, $q$Trim Die Cost$q$, $q$Trim Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Lowest Trim Die Cost}$q$, 19, false),
    (v_id, $q$Pierce Die Cost$q$, $q$Pierce Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Pierced Holes} * {Lowest Pierce Die Cost}$q$, 20, false),
