    (v_id, $q$Die Sets$q$, $q$Die Sets$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, CEIL({Lifetime Volume} / {Tool Life}))$q$, 22, false),
    (v_id, $q$Tooling Cost$q$, $q$Tooling Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Die Sets} * {Die Set Cost}$q$, 23, false),
    (v_id, $q$Cost per Part$q$, $q$Cost per Part (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Tooling Cost} / {Lifetime Volume}$q$, 24, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Forging - Forged shape$q$, 11, 0),
    ($q$Forging - Flash$q$, 14, 0),
    ($q$Forging - Billet$q$, 8, 0),
    ($q$Forging - Bar$q$, 10, 0),
    ($q$Forging - Material cost$q$, 9, 0),
    ($q$Forging - Band saw$q$, 8, 1),
    ($q$Forging - Induction heating$q$, 15, 1),
    ($q$Forging - Forging load$q$, 16, 0),
    ($q$Forging - Press$q$, 8, 1),
    ($q$Forging - Mechanical press$q$, 3, 1),
    ($q$Forging - Trim$q$, 11, 1),
    ($q$Forging - Die tooling$q$, 24, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Forging$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1051: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
